type structTypeInfo struct {
	fields     []fieldInfo
	isVolatile bool // true if any field is volatile (is_volatile_struct_union)
	isConst    bool // true if any field is const (is_const_struct_union)
}

type unionTypeInfo struct {
	fields     []fieldInfo
	isVolatile bool
	isConst    bool
}

type fieldInfo struct {
	name     string
	ctype    CType
	bitfield bool
	bitWidth int
}

type globalInfo struct {
	name       string
	ctype      CType
	isConst    bool
	isVolatile bool
	isArray    bool
	arrayLen   int
	// arraySizes: full CreateArray dimensions for multi-dim itemize
	// (seed4 e2371 U9 U4 U7 on [9][4][7]).
	arraySizes []int
	// fromParentLocal: materialised via createLocalPathGlobalDirectInit.
	// C++ GenerateNewParentLocal only fills block->local_vars — exclude from
	// SelectGlobal when globalSimpleESimpleDone (seed5 e607 live U4).
	fromParentLocal bool
}

type arrayInfo struct {
	name  string
	ctype CType
	len   int
}

// mustReadArrayEntry tracks one ArrayVariable in rw_directive must_read_vars
// (StatementFor::make_random_array_loop access 0/2). Used by
// VariableSelector::select_must_use_var → itemize_array + F75.
type mustReadArrayEntry struct {
	name  string
	ctype CType // element type (Variable::type for arrays)
	sizes []int
}

type pointerInfo struct {
	name            string
	target          string
	targetTy        CType
	volatilePointer bool
	volatileTarget  bool
	constTarget     bool
}

type paramInfo struct {
	name  string
	ctype CType
	// constLevels mirrors CVQualifiers::is_consts (pointer levels then self)
	// from GenerateParameterVariable random_qualifiers draws.
	constLevels []bool
}

type funcInfo struct {
	name   string
	ret    CType
	params []paramInfo
}

